import React from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  return (
    <>
<div className="bg-red-600 text-white min-h-screen">
    <div className="flex flex-row mx-auto w-fit ">

        <div className="flex flex-col justify-center items-center text-center p-4">
           {/* Graphic and Communication Designer in a different format */}
           <span className="text-2xl font-semibold text-white-600 italic mt-2">
                    GRAPHIC AND COMMUNICATION DESIGNER
                  </span>
        <p class=""><span class="wixui-rich-text__text">Hi there!</span></p>



          {/* Rest of the description */}
            <p className="text-black text-lg font-normal text-3xl leading-8 max-w-[600px] mt-4">
              <span className="font-serif">I craft visuals that tell stories</span>  
              <span className="font-mono"> to connect people</span>  
              <span className="font-semibold italic"> and strive to make design both meaningful and impactful.</span>  
              <span className="font-extrabold font-cursive text-gray-700"> Let’s bring ideas to life!</span>  
            </p>

        </div>

    </div>
</div>


    </>
  );
};

export default Home;
